type JSONPrimitive = boolean | Date | null | number | string;
type JSONObject = {
    [prop: string]: JSONValue;
};
interface JSONArray extends Array<JSONValue> {
    [index: number]: JSONValue;
}
export type JSONValue = JSONPrimitive | JSONObject | JSONArray;
export {};
